from taf.config.testline import CloudBts as CloudBtsConfig

from taf.rfrl.procedures.resources.python.bts.bts.bts import Bts
from taf.rfrl.procedures.resources.python.bts.bts.cloud_bts import CloudBts
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import UnsupportedBtsType
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import BtsConfig


@pretty_log
def create_bts(bts_config: BtsConfig) -> Bts:
    """
    Creates appropriate BTS based on provided configuration.
    Created BTS has no open connections and its components are not loaded.
    :param bts_config: BTS configuration details from init file
    :return: instance of appropriate BTS class
    :raises UnsupportedBtsType: if type of provided BTS configuration is not supported
    """
    if isinstance(bts_config, CloudBtsConfig):
        bts_cu_http = bts_config.cu.oam_http_connection_details
        bts = CloudBts(ip=bts_cu_http.addr,
                       port=bts_cu_http.port,
                       user_name=bts_cu_http.username,
                       password=bts_cu_http.password,
                       bts_init_config=bts_config)
    else:
        raise UnsupportedBtsType(f'Unsupported type of BTS configuration ({type(bts_config)}) provided')

    return bts
